// ETF Quality Score Integration
// Auto-generated by Alfred
(function() {
  var SCORE_LABELS = {
    'ACHAT_immediat': '★',
    'Acheter': '●',
    'Conserver': '●',
    'Surveiller': '●',
    'Remplacer': '●',
    'Vendre': '●'
  };

  function addScoreColumn() {
    var tbody = document.querySelector('#etf-table tbody');
    if (!tbody) return;
    
    var rows = tbody.querySelectorAll('tr');
    if (rows.length === 0) return;
    
    var firstRow = rows[0];
    if (firstRow.cells.length >= 9) return;
    
    if (firstRow.cells.length === 1) {
      firstRow.cells[0].colSpan = 10;
      return;
    }
    
    for (var i = 0; i < rows.length; i++) {
      var tr = rows[i];
      var isin = tr.getAttribute('data-isin');
      var score = '-';
      var label = '';
      
      if (window.ETF_SCORES && isin) {
        for (var j = 0; j < window.ETF_SCORES.length; j++) {
          if (window.ETF_SCORES[j].isin === isin) {
            score = window.ETF_SCORES[j].total;
            label = window.ETF_SCORES[j].decision;
            break;
          }
        }
      }
      
      var td = document.createElement('td');
      td.style.textAlign = 'center';
      td.style.fontWeight = 'bold';
      
      if (score !== '-') {
        var color = '#dc3545';
        if (score >= 95) color = '#ffd700';
        else if (score >= 90) color = '#28a745';
        else if (score >= 85) color = '#007bff';
        else if (score >= 80) color = '#ffc107';
        else if (score >= 70) color = '#fd7e14';
        
        td.style.color = color;
        td.textContent = score + '/100';
        td.title = label;
      } else {
        td.textContent = '-';
      }
      
      tr.appendChild(td);
    }
  }

  var timeout = null;
  var observer = new MutationObserver(function() {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(addScoreColumn, 100);
  });
  
  function init() {
    var tbody = document.querySelector('#etf-table tbody');
    if (tbody) {
      observer.observe(tbody, { childList: true, subtree: true });
      addScoreColumn();
    } else {
      setTimeout(init, 500);
    }
  }
  
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
